type View = "home" | "learn" | "practice" | "cases" | "schema" | "interview" | "concepts" | "history" | "projects" | "mastery" | "graduation";
type Row = Record<string, unknown>;
type Lesson = { id:number; title:string; level:string; text:string; sql:string; takeaway:string; tip:string };
type LessonSeed = [string,string,string,string,string,string,string];
type Project = {id:string; title:string; icon:string; dataset:string; difficulty:string; business:string; stakeholder:string; outcome:string; tasks:{id:number;title:string;prompt:string;starter:string;check:(rows:Row[])=>boolean}[]};
type Exercise = { id:number; dataset:string; title:string; difficulty:string; topic:string; prompt:string; starter:string; hint:string; explanation:string; check:(rows:Row[])=>boolean };

const lessonSeeds: LessonSeed[] = [
  ["SELECT","Your First SELECT","FOUNDATIONS","Choose the columns you need and understand the grain of a table.","SELECT customer_id, name\nFROM customers;","SELECT chooses columns; FROM chooses the source table.","Start with the business question, then choose only the columns needed."],
  ["WHERE","Filtering with WHERE","FOUNDATIONS","Filter rows using equality, ranges, IN, BETWEEN and boolean logic.","SELECT name, city\nFROM customers\nWHERE city = 'Delhi';","WHERE filters rows before aggregation.","Put row-level filters in WHERE, not HAVING."],
  ["ORDER","Sorting Results","FOUNDATIONS","Control result order with ASC, DESC and multiple sort keys.","SELECT name, lifetime_value\nFROM customers\nORDER BY lifetime_value DESC;","ORDER BY changes presentation, not the underlying data.","Always add a deterministic tie-breaker when order matters."],
  ["DISTINCT","DISTINCT & Duplicates","FOUNDATIONS","Return unique values and recognize when duplicates are meaningful.","SELECT DISTINCT city\nFROM customers\nORDER BY city;","DISTINCT removes duplicate result rows.","Do not use DISTINCT to hide a bad join."],
  ["NULL","NULL & Missing Data","FOUNDATIONS","Handle unknown or missing values correctly with IS NULL, COALESCE and NULL-safe logic.","SELECT *\nFROM customers\nWHERE lifetime_value IS NULL;","NULL is not equal to 0 or an empty string.","Use IS NULL / IS NOT NULL for missingness checks."],
  ["CASE","CASE WHEN","FOUNDATIONS","Turn raw values into business categories, flags and buckets.","SELECT name, CASE WHEN lifetime_value >= 50000 THEN 'VIP' ELSE 'Core' END AS segment\nFROM customers;","CASE embeds business rules in SQL.","Order overlapping conditions from most specific to least specific."],
  ["COUNT","COUNT & Aggregates","AGGREGATION","Use COUNT, SUM, AVG, MIN and MAX to create metrics.","SELECT COUNT(*) AS customers, AVG(lifetime_value) AS avg_ltv\nFROM customers;","Aggregates summarize many rows into metrics.","COUNT(*) counts rows; COUNT(column) ignores NULLs."],
  ["GROUP","GROUP BY","AGGREGATION","Move from row-level data to segmented reporting.","SELECT city, COUNT(*) AS customers\nFROM customers\nGROUP BY city;","GROUP BY creates one result row per group.","Every selected non-aggregated column generally belongs in GROUP BY."],
  ["HAVING","HAVING","AGGREGATION","Filter aggregated groups after GROUP BY.","SELECT city, SUM(amount) AS revenue\nFROM orders o JOIN customers c ON c.customer_id=o.customer_id\nGROUP BY city\nHAVING SUM(amount) > 30000;","WHERE filters rows; HAVING filters groups.","If the condition depends on an aggregate, think HAVING."],
  ["JOIN","INNER JOIN","JOINS","Combine matching records across related tables.","SELECT c.name, o.amount\nFROM customers c\nJOIN orders o ON c.customer_id=o.customer_id;","INNER JOIN keeps matching records from both tables.","Before joining, state the grain of each table and the expected row multiplication."],
  ["LEFT","LEFT JOIN","JOINS","Preserve the left table to find missing relationships.","SELECT c.name\nFROM customers c\nLEFT JOIN orders o ON c.customer_id=o.customer_id\nWHERE o.order_id IS NULL;","LEFT JOIN is the classic pattern for 'who did not...' questions.","A WHERE condition on the right table can accidentally turn a LEFT JOIN into an INNER JOIN."],
  ["MULTI","Multi-table Joins","JOINS","Join three or more tables while keeping keys and grain under control.","SELECT o.order_id, c.name, p.category\nFROM orders o\nJOIN customers c ON c.customer_id=o.customer_id\nJOIN products p ON p.product_id=o.product_id;","Multiple joins are a chain of relationships.","Validate row counts after each join when debugging duplicates."],
  ["SUBQUERY","Subqueries","INTERMEDIATE","Use a query inside another query for filtering or derived metrics.","SELECT name\nFROM customers\nWHERE customer_id IN (SELECT customer_id FROM orders);","Subqueries let one query feed another.","If nested logic becomes hard to read, consider a CTE."],
  ["CTE","Common Table Expressions","INTERMEDIATE","Break complex analytical SQL into named, testable steps.","WITH revenue AS (SELECT customer_id, SUM(amount) total FROM orders GROUP BY customer_id)\nSELECT * FROM revenue ORDER BY total DESC;","CTEs improve structure and debugging.","Build one logical step at a time and inspect intermediate results."],
  ["UNION","UNION & UNION ALL","INTERMEDIATE","Stack compatible result sets vertically.","SELECT customer_id FROM web_customers\nUNION ALL\nSELECT customer_id FROM store_customers;","UNION removes duplicates; UNION ALL preserves them.","The two SELECTs must have compatible column positions and types."],
  ["EXISTS","EXISTS & Anti-Joins","INTERMEDIATE","Check whether a related record exists without needing its columns.","SELECT c.name\nFROM customers c\nWHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.customer_id);","EXISTS answers 'does a matching row exist?'.","EXISTS is often cleaner than DISTINCT when you only need presence."],
  ["DATES","Date SQL","INTERMEDIATE","Extract periods, calculate date differences and build monthly reporting.","SELECT DATE_TRUNC('month', order_date) AS month, SUM(amount) AS revenue\nFROM orders\nGROUP BY 1\nORDER BY 1;","Dates are essential for trend and cohort analysis.","Choose the reporting grain explicitly: day, week, month or quarter."],
  ["ROW","ROW_NUMBER","WINDOWS","Rank rows within groups without collapsing the dataset.","SELECT customer_id, order_date, amount, ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date) AS purchase_no\nFROM orders;","ROW_NUMBER assigns a unique sequence inside each partition.","Use it to select first/last records and top-N-per-group."],
  ["RANK","RANK & DENSE_RANK","WINDOWS","Compare ranking functions and how ties are handled.","SELECT name, lifetime_value, RANK() OVER(ORDER BY lifetime_value DESC) AS rnk\nFROM customers;","RANK leaves gaps after ties; DENSE_RANK does not.","Pick the ranking function based on the business definition of ties."],
  ["LAG","LAG & LEAD","WINDOWS","Compare a row with the previous or next row.","SELECT month, revenue, LAG(revenue) OVER(ORDER BY month) AS prior_month\nFROM monthly_revenue;","LAG and LEAD create period-over-period comparisons.","Always define the ORDER BY that determines what 'previous' means."],
  ["RUNNING","Running Totals","WINDOWS","Calculate cumulative metrics while retaining row-level detail.","SELECT order_date, amount, SUM(amount) OVER(ORDER BY order_date) AS running_revenue\nFROM orders;","A windowed SUM can accumulate values over time.","For business reporting, confirm whether the running total needs PARTITION BY."],
  ["MOVING","Moving Averages","WINDOWS","Smooth noisy time series with rolling windows.","AVG(revenue) OVER(ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)","Moving averages summarize a rolling period.","A three-row window is not always a three-month window if dates are missing."],
  ["COHORT","Cohort Analysis","ANALYST SQL","Group users by signup period and compare behavior over time.","WITH cohorts AS (SELECT customer_id, DATE_TRUNC('month', signup_date) cohort_month FROM customers) SELECT cohort_month, COUNT(*) FROM cohorts GROUP BY 1;","Cohorts make lifecycle behavior comparable.","Separate cohort assignment from activity measurement."],
  ["RETENTION","Retention","ANALYST SQL","Measure how many users remain active after signup or a prior period.","SELECT cohort_month, activity_month, COUNT(DISTINCT customer_id) active_users\nFROM activity\nGROUP BY 1,2;","Retention is a relationship between a cohort and later activity.","Define the retention event before writing SQL."],
  ["CHURN","Churn & Reactivation","ANALYST SQL","Identify inactive customers and distinguish churn from temporary inactivity.","WITH last_seen AS (SELECT customer_id, MAX(event_date) last_seen FROM events GROUP BY 1) SELECT * FROM last_seen;","Churn requires a clear inactivity window.","Write the business definition first: e.g. no activity for 60 days."],
  ["FUNNEL","Funnel Analysis","ANALYST SQL","Measure progression from one event to the next.","SELECT COUNT(DISTINCT CASE WHEN event='view' THEN user_id END) views, COUNT(DISTINCT CASE WHEN event='purchase' THEN user_id END) buyers FROM events;","Funnels quantify conversion between stages.","Use DISTINCT users when the metric is user conversion, not event volume."],
  ["SEGMENT","Customer Segmentation","ANALYST SQL","Create useful segments from behavior, value and recency.","CASE WHEN orders_90d >= 5 AND spend_90d >= 50000 THEN 'High Value' ... END","Segments translate metrics into action-oriented groups.","Make thresholds explicit and validate segment sizes."],
  ["KPI","KPI Design in SQL","ANALYST SQL","Build trustworthy metrics with numerators, denominators and grain.","SELECT SUM(resolved_within_sla)::DOUBLE / NULLIF(COUNT(*),0) AS sla_rate FROM tickets;","A KPI is a definition, not just a SQL expression.","Always validate numerator, denominator, time window and population."],
  ["QUALITY","Data Quality Checks","ANALYST SQL","Detect duplicates, missing keys, invalid dates and broken relationships.","SELECT customer_id, COUNT(*) FROM customers GROUP BY 1 HAVING COUNT(*) > 1;","Quality SQL protects downstream analysis.","Turn recurring checks into reusable validation queries."],
  ["PERF","SQL Performance Thinking","ADVANCED","Reason about filters, joins, aggregation and query plans.","SELECT ... FROM large_fact f JOIN dim d ON ... WHERE f.event_date >= DATE '2026-01-01';","Correct SQL comes first; performance follows from data volume and execution strategy.","Filter early, join on keys, avoid unnecessary columns and inspect plans when available."],
  ["DEBUG","Debugging SQL","ADVANCED","Use row counts, samples and intermediate CTEs to isolate errors.","WITH step1 AS (...), step2 AS (...) SELECT COUNT(*) FROM step2;","Debugging is a repeatable process, not guesswork.","Compare expected grain with actual grain after every transformation."],
  ["PROJECT","Analyst SQL Project","CAPSTONE","Combine joins, windows, KPIs and business reasoning in a full analysis.","WITH ... SELECT ...;","A senior analyst explains what the query means for the business.","Finish with an insight, implication and recommended next question."],
];

const lessons: Lesson[] = lessonSeeds.map(([key,title,level,text,sql,takeaway,tip],i)=>({id:i+1,title,level,text,sql,takeaway,tip}));

